    void save_hdf5(lasyten::hdf5::Saver& saver,
                   HighFive::Group& h5gr,
                   std::string subpath) override
    {
        py::gil_scoped_acquire gil;
        py::function ov = py::get_overload(static_cast<TensorBackend*>(this), "save_hdf5");
        if (ov) {
            py::object* ps = lasyten::hdf5::tls_py_saver();
            py::object* pg = lasyten::hdf5::tls_py_h5gr();
            if (!ps || !pg)
                py::pybind11_fail(
                  "TensorBackend.save_hdf5 Python override requires an active hdf5 PyBridge");
            ov(*ps, *pg, subpath);
            return;
        }
        TensorBackend::save_hdf5(saver, h5gr, std::move(subpath));
    }
